mapper.select:
select distinct fi.id,fi.field_address,fi.user_id,fi.start_time,fi.company_id,
fi.end_time,fi.refuse_reason,fi.field_reason,fi.approval_people_id,fi.approval_status,TIMESTAMPDIFF(MINUTE,start_time,end_time) as fieldTime,fi.crt_time ,fi.upd_time
from
field_info fi  LEFT JOIN copy_info ci ON ci.apply_id = fi.id and ci.apply_type = 2


        and ci.user_id = #{copyId}


        and fi.id = #{id}


        and fi.user_id = #{userId}


        and fi.approval_people_id = #{approvalPeopleId}


        and fi.approval_status = #{approvalStatus}


        and fi.approval_status in (1,2)


        and fi.crt_time >= #{startTime} and fi.crt_time <= #{endTime}


order by fi.crt_time desc

select t.id, t.user_id as userId, t.company_id as companyId, t.field_reason as fieldReason, t.field_address as fieldAddress, t.start_time as startTime, t.end_time as endTime, t.approval_people_id as approvalPeopleId, t.approval_status as approvalStatus from field_info t
and t.approval_status = #{queryForm.approvalStatus}
and t.user_id = #{queryForm.userId}
and t.company_id = #{queryForm.companyId}
and DATE_FORMAT(t.start_time,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andDate},'%Y-%m-%d')
order by t.start_time asc

select id, userId, crtTime, startTime, endTime, approvalPeopleId, STATUS, approvalStatus from (select id,user_id as userId,crt_time as crtTime,work_date as startTime,work_date as endTime,approval_people_id as approvalPeopleId,'加班' as status,approval_status as approvalStatus from work_overtime_info
AND DATE_FORMAT(crt_time,'%Y-%m-%d') = DATE_FORMAT(#{crtTime},'%Y-%m-%d')
AND DATE_FORMAT(work_date,'%Y-%m-%d') = DATE_FORMAT(#{startTime},'%Y-%m-%d')
AND user_id = #{userId}
AND approval_status = #{approvalStatus}
union all select id,user_id as userId,crt_time as crtTime,start_time as startTime,end_time as endTime,approval_people_id as approvalPeopleId,'外勤' as status,approval_status as approvalStatus from field_info
AND DATE_FORMAT(crt_time,'%Y-%m-%d') = DATE_FORMAT(#{crtTime},'%Y-%m-%d')
AND DATE_FORMAT(start_time,'%Y-%m-%d') = DATE_FORMAT(#{startTime},'%Y-%m-%d')
AND user_id = #{userId}
AND approval_status = #{approvalStatus}
union all select li.id as id,li.user_id as userId,li.crt_time as crtTime,li.start_time as startTime,li.end_time as endTime,GROUP_CONCAT(ap.user_id) as approvalPeopleId,'请假' as status,li.approval_status as approvalStatus from leave_info li LEFT JOIN approval_info ai on ai.leave_id = li.id LEFT JOIN approval_people ap on ap.id = ai.approval_people_id
AND DATE_FORMAT(li.crt_time,'%Y-%m-%d') = DATE_FORMAT(#{crtTime},'%Y-%m-%d')
AND DATE_FORMAT(li.start_time,'%Y-%m-%d') = DATE_FORMAT(#{startTime},'%Y-%m-%d')
AND li.user_id = #{userId}
AND li.approval_status = #{approvalStatus}
GROUP BY li.id) a
AND a.status = #{status}
order by a.crtTime desc
